test-case.test:
(: FTAnd-q1: Basic syntax :)
declare variable $input-context external;
$input-context/books/book[para contains text "software" ftand "ninja"]/title

(: FTAnd-q2: 'and' instead of 'ftand'; 'and "ninja"' is a no-op :)
declare variable $input-context external;
$input-context/books/book[para contains text "software" and "ninja"]/title

(: FTAnd-q3: Both branches fail :)
declare variable $input-context external;
fn:count($input-context/books/book[para contains text "dingbat" ftand "numbskull"]/title)

(: FTAnd-q4: One branch false :)
declare variable $input-context external;
fn:count($input-context/books/book[para contains text "software" ftand "numbskull"]/title)

(: FTAnd-q5: One branch false :)
declare variable $input-context external;
fn:count($input-context/books/book[para contains text "numbskull" ftand "software"]/title)

(: FTAnd-badexpr1: Bad computed expression :)
declare variable $input-context external;
$input-context/books/book[para contains text {(47)} ftand "ninja"]/title

(: FTAnd-andor: Test and/or precedence :)
declare variable $input-context external;
$input-context/books/book[para contains text "numbskull" ftand "software" ftor "ninja"]/title
